import{_ as t,o as r,c as a,a4 as o}from"./chunks/framework.BoUsC9QI.js";const m=JSON.parse('{"title":"Browser support","description":"Neba supports Chrome and Edge 111, Firefox 113 and Safari 16.4, and every later release of each, on desktop and on mobile. All four were released between March…","frontmatter":{"title":"Browser support"},"headers":[],"relativePath":"browser-support.md","filePath":"en/browser-support.md","lastUpdated":1789433132000}'),n={name:"browser-support.md"};function i(s,e,d,l,h,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="browser-support" tabindex="-1">Browser support <a class="header-anchor" href="#browser-support" aria-label="Permalink to &quot;Browser support&quot;">​</a></h1><p>Neba supports Chrome and Edge 111, Firefox 113 and Safari 16.4, and every later release of each, on desktop and on mobile. All four were released between March and May 2023. Older browsers are not supported: without <code>color-mix()</code> most of the colours are not drawn, and further back the components stop running at all.</p><h2 id="minimum-versions" tabindex="-1">Minimum versions <a class="header-anchor" href="#minimum-versions" aria-label="Permalink to &quot;Minimum versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Browser</th><th>Minimum version</th><th>Released</th></tr></thead><tbody><tr><td>Chrome, Chrome for Android</td><td>111</td><td>March 2023</td></tr><tr><td>Edge</td><td>111</td><td>March 2023</td></tr><tr><td>Firefox, Firefox for Android</td><td>113</td><td>May 2023</td></tr><tr><td>Safari on macOS, iOS and iPadOS</td><td>16.4</td><td>March 2023</td></tr></tbody></table><ul><li>Other Chromium-based browsers, such as Opera and Samsung Internet, are supported from the release built on Chromium 111.</li><li>A browser on iOS or iPadOS that uses the system&#39;s WebKit engine follows the Safari row, so what counts is the OS version of the device. An iPhone or iPad that cannot update past iOS 15 or iPadOS 15 is outside the range.</li><li>Every Firefox ESR release from 115 onwards is inside the range.</li></ul><p>The test suite runs against the current releases of Chromium, Firefox and WebKit, so the minimum versions are not tested in a browser. They are derived from the features in the next section and from the range Neba&#39;s dependencies declare, and on every change a CI check compares what the stylesheet and the source use against <a href="https://github.com/mdn/browser-compat-data" target="_blank" rel="noreferrer">MDN&#39;s compatibility data</a>.</p><p>To keep your build from transpiling for browsers Neba does not render in, target the same range. As a <a href="https://browsersl.ist" target="_blank" rel="noreferrer">Browserslist</a> query:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chrome &gt;= 111, edge &gt;= 111, firefox &gt;= 113, safari &gt;= 16.4, ios_saf &gt;= 16.4</span></span></code></pre></div><h2 id="what-sets-the-minimum" tabindex="-1">What sets the minimum <a class="header-anchor" href="#what-sets-the-minimum" aria-label="Permalink to &quot;What sets the minimum&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Chrome, Edge</th><th>Firefox</th><th>Safari</th><th>What depends on it</th></tr></thead><tbody><tr><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Values/color_value/color-mix" target="_blank" rel="noreferrer"><code>color-mix()</code></a></td><td>111</td><td>113</td><td>16.2</td><td>Every derived colour token: fills, hover and press states, tints, lines and focus rings</td></tr><tr><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Values/color_value/oklch" target="_blank" rel="noreferrer"><code>oklch()</code></a></td><td>111</td><td>113</td><td>15.4</td><td>The palette those tokens are mixed from</td></tr><tr><td><a href="https://base-ui.com/react/overview/about" target="_blank" rel="noreferrer">Base UI</a> 1.x</td><td>111</td><td>113</td><td>16.4</td><td>Behaviour and accessibility of the interactive components</td></tr><tr><td><a href="https://tailwindcss.com/docs/compatibility" target="_blank" rel="noreferrer">Tailwind CSS</a> v4</td><td>111</td><td>128</td><td>16.4</td><td>The utility classes compiled into <code>neba/styles.css</code></td></tr></tbody></table><p>The minimum for a browser is the highest number in its column, with one exception. Tailwind CSS lists Firefox 128 because of <code>@property</code>, and since v4.1 it ships fallbacks that let Firefox 113 to 127 render the same utilities. If you import <code>neba/tailwind.css</code> into your own Tailwind build, use Tailwind CSS v4.1 or later to keep those fallbacks.</p><h3 id="why-it-cannot-go-lower" tabindex="-1">Why it cannot go lower <a class="header-anchor" href="#why-it-cannot-go-lower" aria-label="Permalink to &quot;Why it cannot go lower&quot;">​</a></h3><p><code>color-mix()</code> is the limit. A colour family is five tokens, and every other shade is mixed from them in the browser, which is also what lets a project override one token and have every state follow. A browser without <code>color-mix()</code> does not fall back to a nearby colour. The token is still defined, but a property that reads it through <code>var()</code> becomes invalid at computed-value time and behaves as <code>unset</code>, so a filled Button has no fill, and hover and press stop changing its colour. Colours precomputed at build time would render, but they would ignore every token a project overrides.</p><p>Base UI declares the same range. Its supported browsers are the ones that implement every feature marked Baseline Widely Available when its last major version was released, which its <a href="https://github.com/mui/base-ui/blob/master/.browserslistrc" target="_blank" rel="noreferrer">Browserslist file</a> lists as Chrome and Edge 111, Firefox 113 and Safari 16.4. A lower minimum would run the interactive components on browsers their primitives do not support.</p><p>Transpiling or polyfilling does not change this. The JavaScript is not the limit: without checking for it first, the code in Neba and Base UI relies on nothing newer than Chrome 102, Firefox 112 and Safari 16, the <code>inert</code> attribute included. A transpiler and polyfills can lower that, but nothing can add <code>color-mix()</code> to a browser.</p><h2 id="differences-inside-the-range" tabindex="-1">Differences inside the range <a class="header-anchor" href="#differences-inside-the-range" aria-label="Permalink to &quot;Differences inside the range&quot;">​</a></h2><p>Every browser in the range renders and runs every component. A few details use newer features, and a browser without one of them leaves that detail out.</p><table tabindex="0"><thead><tr><th>Detail</th><th>Needs</th><th>In an older browser inside the range</th></tr></thead><tbody><tr><td>The 2px focus ring on <a href="./components/inputs/text-field">TextField</a>, <a href="./components/inputs/select">Select</a>, <a href="./components/inputs/combobox">Combobox</a>, <a href="./components/inputs/number-field">NumberField</a>, the date and time pickers, <a href="./components/inputs/rating">Rating</a> and a selectable <a href="./components/display/data-table">DataTable</a></td><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Selectors/:has" target="_blank" rel="noreferrer"><code>:has()</code></a>: Firefox 121</td><td>The fields draw no ring and show focus through their border or fill, and a DataTable through its active row. Rating still draws the ring, but on a star focused by a click as well as by the keyboard</td></tr><tr><td>The box or icon beside a label in <a href="./components/inputs/checkbox">Checkbox</a>, <a href="./components/inputs/radio-group">RadioGroup</a>, <a href="./components/inputs/switch">Switch</a>, <a href="./components/feedback/alert">Alert</a> and other rows with a label</td><td>The <code>lh</code> unit: Firefox 120</td><td>It sits at the top of the label&#39;s first line instead of centred on it</td></tr><tr><td>Splitting text into characters and words in <a href="./components/transitions/animate-split">AnimateSplit</a>, <a href="./components/transitions/animate-typing">AnimateTyping</a> and <a href="./components/transitions/animate-scramble">AnimateScramble</a></td><td><a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Intl/Segmenter" target="_blank" rel="noreferrer"><code>Intl.Segmenter</code></a>: Firefox 125</td><td>Text is split by code point and by whitespace. An emoji made of several code points arrives in pieces, and a sentence in a language written without spaces is treated as one word</td></tr><tr><td>The travelling light in <a href="./components/transitions/animate-lighting">AnimateLighting</a></td><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/At-rules/@property" target="_blank" rel="noreferrer"><code>@property</code></a>: Firefox 128</td><td>The light stays in one place</td></tr><tr><td>The first day of the week in <a href="./components/inputs/calendar">Calendar</a> and the date pickers</td><td><a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Intl/Locale/getWeekInfo" target="_blank" rel="noreferrer"><code>Intl.Locale</code> week data</a>: Firefox 153</td><td>The week starts on Sunday unless <code>weekStartsOn</code> is set</td></tr><tr><td>The edge fades of <a href="./components/layout/scroll-area">ScrollArea</a> and <a href="./components/surfaces/tabs">Tabs</a> in a right-to-left layout</td><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Selectors/:dir" target="_blank" rel="noreferrer"><code>:dir()</code></a>: Chrome and Edge 120</td><td>The left and right fades are not swapped</td></tr><tr><td><code>timeline=&quot;view&quot;</code> on the Animate components, such as <a href="./components/transitions/animate-fade">AnimateFade</a></td><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/animation-timeline" target="_blank" rel="noreferrer"><code>animation-timeline</code></a>: Chrome and Edge 115, Safari 26, not yet in Firefox</td><td>The effect runs once on mount instead of following the scroll</td></tr></tbody></table>',18)])])}const f=t(n,[["render",i]]);export{m as __pageData,f as default};
